    IFN_ENGINE_LAYOUT_LOCAL_H(p_w_f16, 6552 * IFN_INKLING_HIDDEN);
    IFN_ENGINE_LAYOUT_LOCAL_F(p_ctrl_msg, P * IFN_INKLING_HIDDEN);
    IFN_ENGINE_LAYOUT_LOCAL_H(p_ctrl_cat_h, P * 4608);
    IFN_ENGINE_LAYOUT_LOCAL_F(p_ctrl_d, P * 64);
