    s->p_ctrl_f = s->p_qrgs;
    s->p_ctrl_g = s->p_qrgs ? s->p_qrgs + P * IFN_INKLING_HIDDEN : NULL;
#undef IFN_ENGINE_LAYOUT_LOCAL_F
